CREATE TABLE budget_fiscal_years(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(20) NOT NULL UNIQUE,start_date DATE NOT NULL,end_date DATE NOT NULL,status ENUM('open','closed','inactive') DEFAULT 'open',created_by INT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,deleted_at TIMESTAMP NULL,CONSTRAINT fk_bfy_user FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE budget_periods(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,fiscal_year_id INT UNSIGNED NOT NULL,period_type ENUM('monthly','quarterly','annual') NOT NULL,period_number TINYINT UNSIGNED NOT NULL,name VARCHAR(100) NOT NULL,start_date DATE NOT NULL,end_date DATE NOT NULL,status ENUM('open','closed') DEFAULT 'open',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_bp_period(fiscal_year_id,period_type,period_number),CONSTRAINT fk_bp_year FOREIGN KEY(fiscal_year_id) REFERENCES budget_fiscal_years(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE budget_categories(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(50) NOT NULL UNIQUE,name VARCHAR(160) NOT NULL,category_type ENUM('operating','investment') DEFAULT 'operating',status ENUM('active','inactive') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,deleted_at TIMESTAMP NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE budgets(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,fiscal_year_id INT UNSIGNED NOT NULL,period_id BIGINT UNSIGNED NOT NULL,site_id INT UNSIGNED NOT NULL,cost_center_id INT UNSIGNED NOT NULL,budget_number VARCHAR(100) NOT NULL UNIQUE,revision_number INT UNSIGNED NOT NULL DEFAULT 0,parent_budget_id BIGINT UNSIGNED NULL,status ENUM('preparation','submitted','pending_df','pending_dg','active','rejected','replaced','cancelled') DEFAULT 'preparation',requires_dg TINYINT(1) NOT NULL DEFAULT 0,total_proposed DECIMAL(16,2) NOT NULL DEFAULT 0,total_validated DECIMAL(16,2) NOT NULL DEFAULT 0,created_by INT UNSIGNED NOT NULL,submitted_at DATETIME NULL,df_validated_by INT UNSIGNED NULL,df_validated_at DATETIME NULL,dg_validated_by INT UNSIGNED NULL,dg_validated_at DATETIME NULL,activated_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,deleted_at TIMESTAMP NULL,KEY idx_budget_scope(site_id,cost_center_id,fiscal_year_id,status),CONSTRAINT fk_budget_year FOREIGN KEY(fiscal_year_id) REFERENCES budget_fiscal_years(id),CONSTRAINT fk_budget_period FOREIGN KEY(period_id) REFERENCES budget_periods(id),CONSTRAINT fk_budget_site FOREIGN KEY(site_id) REFERENCES sites(id),CONSTRAINT fk_budget_center FOREIGN KEY(cost_center_id) REFERENCES cost_centers(id),CONSTRAINT fk_budget_parent FOREIGN KEY(parent_budget_id) REFERENCES budgets(id),CONSTRAINT fk_budget_creator FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE budget_lines(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,budget_id BIGINT UNSIGNED NOT NULL,category_id INT UNSIGNED NOT NULL,proposed_amount DECIMAL(16,2) NOT NULL,validated_amount DECIMAL(16,2) NOT NULL DEFAULT 0,notes VARCHAR(500) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_budget_line(budget_id,category_id),CONSTRAINT fk_bl_budget FOREIGN KEY(budget_id) REFERENCES budgets(id),CONSTRAINT fk_bl_category FOREIGN KEY(category_id) REFERENCES budget_categories(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE budget_history(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,budget_id BIGINT UNSIGNED NOT NULL,old_status VARCHAR(40) NULL,new_status VARCHAR(40) NOT NULL,action VARCHAR(60) NOT NULL,actor_id INT UNSIGNED NOT NULL,reason VARCHAR(500) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_bh_budget FOREIGN KEY(budget_id) REFERENCES budgets(id),CONSTRAINT fk_bh_actor FOREIGN KEY(actor_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE budget_settings(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,site_id INT UNSIGNED NULL,expense_df_threshold DECIMAL(16,2) NOT NULL DEFAULT 10000,dg_budget_threshold DECIMAL(16,2) NOT NULL DEFAULT 100000,warning_percent DECIMAL(6,2) NOT NULL DEFAULT 80,blocking_percent DECIMAL(6,2) NOT NULL DEFAULT 100,updated_by INT UNSIGNED NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_budget_setting_site(site_id),CONSTRAINT fk_bset_site FOREIGN KEY(site_id) REFERENCES sites(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE budget_commitments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,budget_line_id BIGINT UNSIGNED NOT NULL,commitment_number VARCHAR(100) NOT NULL UNIQUE,description VARCHAR(500) NOT NULL,amount DECIMAL(16,2) NOT NULL,realized_amount DECIMAL(16,2) NOT NULL DEFAULT 0,status ENUM('draft','approved','partially_realized','realized','cancelled') DEFAULT 'approved',committed_at DATETIME NOT NULL,created_by INT UNSIGNED NOT NULL,approved_by INT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,deleted_at TIMESTAMP NULL,CONSTRAINT fk_bc_line FOREIGN KEY(budget_line_id) REFERENCES budget_lines(id),CONSTRAINT fk_bc_creator FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE budget_expenses(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,budget_line_id BIGINT UNSIGNED NOT NULL,commitment_id BIGINT UNSIGNED NULL,expense_number VARCHAR(100) NOT NULL UNIQUE,site_id INT UNSIGNED NOT NULL,cost_center_id INT UNSIGNED NOT NULL,description VARCHAR(500) NOT NULL,amount DECIMAL(16,2) NOT NULL,expense_date DATE NOT NULL,status ENUM('pending_df','approved','blocked','derogation_pending','cancelled') DEFAULT 'pending_df',requires_df TINYINT(1) NOT NULL DEFAULT 0,created_by INT UNSIGNED NOT NULL,df_validated_by INT UNSIGNED NULL,df_validated_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,deleted_at TIMESTAMP NULL,CONSTRAINT fk_be_line FOREIGN KEY(budget_line_id) REFERENCES budget_lines(id),CONSTRAINT fk_be_commitment FOREIGN KEY(commitment_id) REFERENCES budget_commitments(id),CONSTRAINT fk_be_site FOREIGN KEY(site_id) REFERENCES sites(id),CONSTRAINT fk_be_center FOREIGN KEY(cost_center_id) REFERENCES cost_centers(id),CONSTRAINT fk_be_creator FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE budget_derogations(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,expense_id BIGINT UNSIGNED NOT NULL,reason VARCHAR(500) NOT NULL,requested_by INT UNSIGNED NOT NULL,status ENUM('pending','approved','rejected') DEFAULT 'pending',approved_by INT UNSIGNED NULL,approved_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_derogation_expense(expense_id),CONSTRAINT fk_bd_expense FOREIGN KEY(expense_id) REFERENCES budget_expenses(id),CONSTRAINT fk_bd_requester FOREIGN KEY(requested_by) REFERENCES users(id),CONSTRAINT fk_bd_approver FOREIGN KEY(approved_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE budget_df_delegations(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,delegator_id INT UNSIGNED NOT NULL,delegate_id INT UNSIGNED NOT NULL,site_id INT UNSIGNED NULL,starts_at DATETIME NOT NULL,expires_at DATETIME NOT NULL,status ENUM('pending','approved','rejected','revoked','expired') DEFAULT 'pending',reason VARCHAR(255) NOT NULL,requested_by INT UNSIGNED NOT NULL,approved_by INT UNSIGNED NULL,approved_at DATETIME NULL,revoked_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,deleted_at TIMESTAMP NULL,CONSTRAINT fk_bdd_delegator FOREIGN KEY(delegator_id) REFERENCES users(id),CONSTRAINT fk_bdd_delegate FOREIGN KEY(delegate_id) REFERENCES users(id),CONSTRAINT fk_bdd_site FOREIGN KEY(site_id) REFERENCES sites(id),CONSTRAINT fk_bdd_requester FOREIGN KEY(requested_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE budget_df_delegation_events(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,delegation_id BIGINT UNSIGNED NOT NULL,event_type ENUM('requested','approved','rejected','revoked','expired') NOT NULL,actor_id INT UNSIGNED NULL,details VARCHAR(500) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_bdde_delegation FOREIGN KEY(delegation_id) REFERENCES budget_df_delegations(id),CONSTRAINT fk_bdde_actor FOREIGN KEY(actor_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE budget_alerts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,budget_line_id BIGINT UNSIGNED NOT NULL,threshold_percent INT UNSIGNED NOT NULL,consumption_percent DECIMAL(8,2) NOT NULL,status ENUM('active','acknowledged') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,acknowledged_at DATETIME NULL,UNIQUE KEY uq_ba_line_threshold(budget_line_id,threshold_percent),CONSTRAINT fk_ba_line FOREIGN KEY(budget_line_id) REFERENCES budget_lines(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT IGNORE INTO budget_categories(code,name,category_type) VALUES('INTRANTS','Intrants et matières','operating'),('MO','Main-d’œuvre','operating'),('ENERGIE','Énergie','operating'),('MAINT','Maintenance','operating'),('LOG','Logistique','operating'),('INVEST','Investissements','investment');
INSERT INTO budget_settings(site_id) VALUES(NULL);
INSERT IGNORE INTO permissions(component,action,description) VALUES('budgets','read','Consulter budgets'),('budgets','create','Préparer budgets'),('budgets','validate','Valider budgets et dépenses'),('budgets','update','Réviser et engager'),('budgets','delete','Annuler budgets'),('budgets','administer','Configurer budgets');
INSERT IGNORE INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r JOIN permissions p ON p.component='budgets' WHERE r.slug IN('administrateur','administrateur-systeme');
INSERT IGNORE INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r JOIN permissions p ON p.component='budgets' AND p.action IN('read','create','update') WHERE r.slug IN('comptable','directeur-site','responsable-site');
INSERT IGNORE INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r JOIN permissions p ON p.component='budgets' AND p.action IN('read','validate','administer') WHERE r.slug IN('directeur-financier','directeur-general','direction');
